private void LoadOldUsingFromDevice()
{
    if (uDevice.DeviceID == null || uDevice.DeviceID <= 0)
        return;

    FAM_Device objDevice = new FAM_Device();
    objDevice.DeviceID = uDevice.DeviceID;
    if (!objDevice.Get())
        return;

    uOldOffice.EditValue = objDevice.OfficeID;
    lookupOldPlaceID.EditValue = objDevice.PlaceID;
    txtOldUsingFor.Text = objDevice.UsingFor;

    if (objDevice.UsingEmployeeID == null || objDevice.UsingEmployeeID == 0)
        lookupOldUsingEmployeeID.EditValue = null;
    else
        lookupOldUsingEmployeeID.EditValue = objDevice.UsingEmployeeID;
}

