input.contents:
/*
	Patch  : [dbo].[FAM_Device_EditUsingInfo] - Thêm cập nhật chi nhánh, công trình
	Date   : 2025-09-15
	Module : FAM
	Lỗi / Yêu cầu:
		Phiếu luân chuyển cập nhật tài sản theo chi nhánh QL, công trình SD, người sử dụng
	Cách chạy:
		SSMS → chọn đúng database → F5 chạy toàn file.
*/

If Object_Id(N'dbo.FAM_Device_EditUsingInfo', N'P') Is Not Null
Begin
	Exec(N'
Alter Procedure [dbo].[FAM_Device_EditUsingInfo]
	@DeviceID bigint,
	@UsingFor nvarchar(500) = null,
	@OfficeID int = null,
	@PlaceID int = null,
	@UsingDepartmentID int = null,
	@UsingRoomID nvarchar(50) = null,
	@UsingEmployeeID bigint = null,
	@UpdatedUser nvarchar(50) = null
As
Begin
	Set Nocount On;

	Update FAM_Device
	Set
		UsingFor = @UsingFor,
		OfficeID = IsNull(@OfficeID, 0),
		PlaceID = IsNull(@PlaceID, 0),
		UsingDepartmentID = IsNull(@UsingDepartmentID, 0),
		UsingRoomID = IsNull(@UsingRoomID, N''''),
		UsingEmployeeID = IsNull(@UsingEmployeeID, 0),
		UpdatedUser = @UpdatedUser,
		UpdatedDate = GetDate()
	Where
		DeviceID = @DeviceID;
End
');
End
Go

