/*
	Patch  : FAM_MoveVoucherDetail - GET / SEARCH / ADD / EDIT
	Date   : 2025-09-15
	Module : FAM
	Mô tả  : Đồng bộ store luân chuyển tài sản theo chi nhánh QL, công trình SD, người sử dụng
	Cách chạy:
		SSMS → chọn đúng database → F5 chạy toàn file.
*/

Set Nocount On;
Go

If Object_Id(N'dbo.FAM_MoveVoucherDetail_GET', N'P') Is Not Null
	Drop Procedure dbo.FAM_MoveVoucherDetail_GET;
Go

Create Procedure dbo.FAM_MoveVoucherDetail_GET
(
	@MoveVoucherDetailID bigint
)
As
Begin
	Set Nocount On;

	Select
		FAM_MoveVoucherDetail.MoveVoucherDetailID,
		FAM_MoveVoucherDetail.MoveVoucherCode,
		FAM_MoveVoucherDetail.DeviceID,
		FAM_MoveVoucherDetail.RequestEmployeeID,
		FAM_MoveVoucherDetail.RequestDate,
		FAM_MoveVoucherDetail.Reason,
		FAM_MoveVoucherDetail.MoveEmployeeID,
		FAM_MoveVoucherDetail.MoveDate,
		FAM_MoveVoucherDetail.MoveContent,
		FAM_MoveVoucherDetail.OldUsingFor,
		FAM_MoveVoucherDetail.OldOfficeID,
		FAM_MoveVoucherDetail.OldPlaceID,
		FAM_MoveVoucherDetail.OldUsingDepartmentID,
		FAM_MoveVoucherDetail.OldUsingRoomID,
		FAM_MoveVoucherDetail.OldUsingEmployeeID,
		FAM_MoveVoucherDetail.NewUsingFor,
		FAM_MoveVoucherDetail.NewOfficeID,
		FAM_MoveVoucherDetail.NewPlaceID,
		FAM_MoveVoucherDetail.NewUsingDepartmentID,
		FAM_MoveVoucherDetail.NewUsingRoomID,
		FAM_MoveVoucherDetail.NewUsingEmployeeID,
		FAM_MoveVoucherDetail.IsReviewed,
		FAM_MoveVoucherDetail.ReviewComment,
		FAM_MoveVoucherDetail.ReviewUser,
		FAM_MoveVoucherDetail.ReviewDate,
		FAM_MoveVoucherDetail.Description,
		FAM_MoveVoucherDetail.CreatedDate,
		FAM_MoveVoucherDetail.CreatedUser,
		FAM_MoveVoucherDetail.UpdatedDate,
		FAM_MoveVoucherDetail.UpdatedUser,
		FAM_MoveVoucherDetail.IsDeleted,
		FAM_MoveVoucherDetail.DeletedDate,
		FAM_MoveVoucherDetail.DeletedUser
	From FAM_MoveVoucherDetail
	Where FAM_MoveVoucherDetail.MoveVoucherDetailID = @MoveVoucherDetailID
		and FAM_MoveVoucherDetail.IsDeleted = 0;
End
Go

If Object_Id(N'dbo.FAM_MoveVoucherDetail_SEARCH', N'P') Is Not Null
	Drop Procedure dbo.FAM_MoveVoucherDetail_SEARCH;
Go

Create Procedure dbo.FAM_MoveVoucherDetail_SEARCH
(
	@Keyword nvarchar(200) = null,
	@DeviceKindID int = null,
	@DeviceStatusID int = null,
	@InputVoucherDateFrom datetime = null,
	@InputVoucherDateTo datetime = null,
	@OldOfficeID int = null,
	@OldPlaceID int = null,
	@NewOfficeID int = null,
	@NewPlaceID int = null
)
As
Begin
	Set Nocount On;

	Select
		Cast(0 as bit) as IsSelected,
		FAM_MoveVoucherDetail.MoveVoucherDetailID,
		FAM_MoveVoucherDetail.MoveVoucherCode,
		FAM_MoveVoucherDetail.DeviceID,
		FAM_Device.DeviceCode,
		FAM_Device.DeviceName,
		FAM_DeviceKind.DeviceKindName,
		FAM_DeviceStatus.DeviceStatusName,
		FAM_Device.InputVoucherDate,
		FAM_MoveVoucherDetail.RequestDate,
		FAM_MoveVoucherDetail.MoveDate,
		FAM_MoveVoucherDetail.Reason,
		FAM_MoveVoucherDetail.MoveContent,
		FAM_MoveVoucherDetail.RequestEmployeeID,
		RequestEmployee.Fullname as RequestEmployeeName,
		FAM_MoveVoucherDetail.MoveEmployeeID,
		MoveEmployee.Fullname as MoveEmployeeName,
		FAM_MoveVoucherDetail.OldOfficeID,
		OldOffice.OfficeName as OldOfficeName,
		FAM_MoveVoucherDetail.OldPlaceID,
		OldPlace.PlaceName as OldPlaceName,
		FAM_MoveVoucherDetail.OldUsingEmployeeID,
		OldUsingEmployee.Fullname as OldUsingEmployeeName,
		FAM_MoveVoucherDetail.OldUsingFor,
		FAM_MoveVoucherDetail.NewOfficeID,
		NewOffice.OfficeName as NewOfficeName,
		FAM_MoveVoucherDetail.NewPlaceID,
		NewPlace.PlaceName as NewPlaceName,
		FAM_MoveVoucherDetail.NewUsingEmployeeID,
		NewUsingEmployee.Fullname as NewUsingEmployeeName,
		FAM_MoveVoucherDetail.NewUsingFor,
		FAM_MoveVoucherDetail.IsReviewed,
		FAM_MoveVoucherDetail.Description,
		FAM_MoveVoucherDetail.CreatedDate,
		FAM_MoveVoucherDetail.CreatedUser
	From FAM_MoveVoucherDetail
		Inner Join FAM_Device on FAM_Device.DeviceID = FAM_MoveVoucherDetail.DeviceID
			and FAM_Device.IsDeleted = 0
		Left Join FAM_DeviceKind on FAM_DeviceKind.DeviceKindID = FAM_Device.DeviceKindID
		Left Join FAM_DeviceStatus on FAM_DeviceStatus.DeviceStatusID = FAM_Device.DeviceStatusID
		Left Join SYS_Office OldOffice on OldOffice.OfficeID = FAM_MoveVoucherDetail.OldOfficeID
		Left Join GEN_Place OldPlace on OldPlace.PlaceID = FAM_MoveVoucherDetail.OldPlaceID
		Left Join SYS_Office NewOffice on NewOffice.OfficeID = FAM_MoveVoucherDetail.NewOfficeID
		Left Join GEN_Place NewPlace on NewPlace.PlaceID = FAM_MoveVoucherDetail.NewPlaceID
		Left Join HRS_Employee RequestEmployee on RequestEmployee.EmployeeID = FAM_MoveVoucherDetail.RequestEmployeeID
		Left Join HRS_Employee MoveEmployee on MoveEmployee.EmployeeID = FAM_MoveVoucherDetail.MoveEmployeeID
		Left Join HRS_Employee OldUsingEmployee on OldUsingEmployee.EmployeeID = FAM_MoveVoucherDetail.OldUsingEmployeeID
		Left Join HRS_Employee NewUsingEmployee on NewUsingEmployee.EmployeeID = FAM_MoveVoucherDetail.NewUsingEmployeeID
	Where FAM_MoveVoucherDetail.IsDeleted = 0
		and
		(
			@Keyword Is Null
			or Ltrim(Rtrim(@Keyword)) = N''
			or FAM_MoveVoucherDetail.MoveVoucherCode like N'%' + @Keyword + N'%'
			or FAM_Device.DeviceCode like N'%' + @Keyword + N'%'
			or FAM_Device.DeviceName like N'%' + @Keyword + N'%'
		)
		and
		(
			@DeviceKindID Is Null
			or @DeviceKindID = 0
			or FAM_Device.DeviceKindID = @DeviceKindID
		)
		and
		(
			@DeviceStatusID Is Null
			or @DeviceStatusID = 0
			or FAM_Device.DeviceStatusID = @DeviceStatusID
		)
		and
		(
			@InputVoucherDateFrom Is Null
			or FAM_Device.InputVoucherDate >= @InputVoucherDateFrom
		)
		and
		(
			@InputVoucherDateTo Is Null
			or FAM_Device.InputVoucherDate < DateAdd(day, 1, Convert(date, @InputVoucherDateTo))
		)
		and
		(
			@OldOfficeID Is Null
			or @OldOfficeID = 0
			or FAM_MoveVoucherDetail.OldOfficeID = @OldOfficeID
		)
		and
		(
			@OldPlaceID Is Null
			or @OldPlaceID = 0
			or FAM_MoveVoucherDetail.OldPlaceID = @OldPlaceID
		)
		and
		(
			@NewOfficeID Is Null
			or @NewOfficeID = 0
			or FAM_MoveVoucherDetail.NewOfficeID = @NewOfficeID
		)
		and
		(
			@NewPlaceID Is Null
			or @NewPlaceID = 0
			or FAM_MoveVoucherDetail.NewPlaceID = @NewPlaceID
		)
	Order By FAM_MoveVoucherDetail.MoveDate desc, FAM_MoveVoucherDetail.MoveVoucherDetailID desc;
End
Go

If Object_Id(N'dbo.FAM_MoveVoucherDetail_ADD', N'P') Is Not Null
	Drop Procedure dbo.FAM_MoveVoucherDetail_ADD;
Go

Create Procedure dbo.FAM_MoveVoucherDetail_ADD
(
	@MoveVoucherCode nvarchar(20) = null,
	@DeviceID bigint = null,
	@RequestEmployeeID bigint = null,
	@RequestDate datetime = null,
	@Reason nvarchar(100) = null,
	@MoveEmployeeID bigint = null,
	@MoveDate datetime = null,
	@MoveContent nvarchar(1000) = null,
	@OldUsingFor nvarchar(500) = null,
	@OldOfficeID int = null,
	@OldPlaceID int = null,
	@OldUsingDepartmentID int = null,
	@OldUsingRoomID nvarchar(50) = null,
	@OldUsingEmployeeID bigint = null,
	@NewUsingFor nvarchar(500) = null,
	@NewOfficeID int = null,
	@NewPlaceID int = null,
	@NewUsingDepartmentID int = null,
	@NewUsingRoomID nvarchar(50) = null,
	@NewUsingEmployeeID bigint = null,
	@IsReviewed bit = 0,
	@ReviewComment nvarchar(500) = null,
	@ReviewUser nvarchar(20) = null,
	@ReviewDate datetime = null,
	@Description nvarchar(500) = null,
	@CreatedUser nvarchar(20) = null
)
As
Begin
	Set Nocount On;

	Insert Into FAM_MoveVoucherDetail
	(
		MoveVoucherCode,
		DeviceID,
		RequestEmployeeID,
		RequestDate,
		Reason,
		MoveEmployeeID,
		MoveDate,
		MoveContent,
		OldUsingFor,
		OldOfficeID,
		OldPlaceID,
		OldUsingDepartmentID,
		OldUsingRoomID,
		OldUsingEmployeeID,
		NewUsingFor,
		NewOfficeID,
		NewPlaceID,
		NewUsingDepartmentID,
		NewUsingRoomID,
		NewUsingEmployeeID,
		IsReviewed,
		ReviewComment,
		ReviewUser,
		ReviewDate,
		Description,
		CreatedUser
	)
	Values
	(
		@MoveVoucherCode,
		IsNull(@DeviceID, 0),
		IsNull(@RequestEmployeeID, 0),
		@RequestDate,
		@Reason,
		IsNull(@MoveEmployeeID, 0),
		@MoveDate,
		@MoveContent,
		@OldUsingFor,
		IsNull(@OldOfficeID, 0),
		IsNull(@OldPlaceID, 0),
		IsNull(@OldUsingDepartmentID, 0),
		IsNull(@OldUsingRoomID, N'0'),
		IsNull(@OldUsingEmployeeID, 0),
		@NewUsingFor,
		IsNull(@NewOfficeID, 0),
		IsNull(@NewPlaceID, 0),
		IsNull(@NewUsingDepartmentID, 0),
		IsNull(@NewUsingRoomID, N'0'),
		IsNull(@NewUsingEmployeeID, 0),
		IsNull(@IsReviewed, 0),
		@ReviewComment,
		@ReviewUser,
		@ReviewDate,
		@Description,
		@CreatedUser
	);

	Select Cast(SCOPE_IDENTITY() as bigint);
End
Go

If Object_Id(N'dbo.FAM_MoveVoucherDetail_EDIT', N'P') Is Not Null
	Drop Procedure dbo.FAM_MoveVoucherDetail_EDIT;
Go

Create Procedure dbo.FAM_MoveVoucherDetail_EDIT
(
	@MoveVoucherDetailID bigint,
	@MoveVoucherCode nvarchar(20) = null,
	@DeviceID bigint = null,
	@RequestEmployeeID bigint = null,
	@RequestDate datetime = null,
	@Reason nvarchar(100) = null,
	@MoveEmployeeID bigint = null,
	@MoveDate datetime = null,
	@MoveContent nvarchar(1000) = null,
	@OldUsingFor nvarchar(500) = null,
	@OldOfficeID int = null,
	@OldPlaceID int = null,
	@OldUsingDepartmentID int = null,
	@OldUsingRoomID nvarchar(50) = null,
	@OldUsingEmployeeID bigint = null,
	@NewUsingFor nvarchar(500) = null,
	@NewOfficeID int = null,
	@NewPlaceID int = null,
	@NewUsingDepartmentID int = null,
	@NewUsingRoomID nvarchar(50) = null,
	@NewUsingEmployeeID bigint = null,
	@IsReviewed bit = 0,
	@ReviewComment nvarchar(500) = null,
	@ReviewUser nvarchar(20) = null,
	@ReviewDate datetime = null,
	@Description nvarchar(500) = null,
	@UpdatedUser nvarchar(20) = null
)
As
Begin
	Set Nocount On;

	Update FAM_MoveVoucherDetail
	Set
		MoveVoucherCode = @MoveVoucherCode,
		DeviceID = IsNull(@DeviceID, 0),
		RequestEmployeeID = IsNull(@RequestEmployeeID, 0),
		RequestDate = @RequestDate,
		Reason = @Reason,
		MoveEmployeeID = IsNull(@MoveEmployeeID, 0),
		MoveDate = @MoveDate,
		MoveContent = @MoveContent,
		OldUsingFor = @OldUsingFor,
		OldOfficeID = IsNull(@OldOfficeID, 0),
		OldPlaceID = IsNull(@OldPlaceID, 0),
		OldUsingDepartmentID = IsNull(@OldUsingDepartmentID, 0),
		OldUsingRoomID = IsNull(@OldUsingRoomID, N'0'),
		OldUsingEmployeeID = IsNull(@OldUsingEmployeeID, 0),
		NewUsingFor = @NewUsingFor,
		NewOfficeID = IsNull(@NewOfficeID, 0),
		NewPlaceID = IsNull(@NewPlaceID, 0),
		NewUsingDepartmentID = IsNull(@NewUsingDepartmentID, 0),
		NewUsingRoomID = IsNull(@NewUsingRoomID, N'0'),
		NewUsingEmployeeID = IsNull(@NewUsingEmployeeID, 0),
		IsReviewed = IsNull(@IsReviewed, 0),
		ReviewComment = @ReviewComment,
		ReviewUser = @ReviewUser,
		ReviewDate = @ReviewDate,
		Description = @Description,
		UpdatedUser = @UpdatedUser,
		UpdatedDate = GetDate()
	Where MoveVoucherDetailID = @MoveVoucherDetailID
		and IsDeleted = 0;
End
Go

