/*
	Patch  : [dbo].[FAM_MoveVoucherDetail_GetNewCode]
	Date   : 2025-09-15
	Module : FAM
	Mô tả  : Sinh số phiếu luân chuyển tự động theo quy ước LC-0000001
	Cách chạy:
		SSMS → chọn đúng database → F5 chạy toàn file.
*/

Set Nocount On;
Go

If Object_Id(N'dbo.FAM_MoveVoucherDetail_GetNewCode', N'P') Is Not Null
	Drop Procedure dbo.FAM_MoveVoucherDetail_GetNewCode;
Go

Create Procedure dbo.FAM_MoveVoucherDetail_GetNewCode
As
Begin
	Set Nocount On;

	Declare @maxNo int;
	Declare @newCode nvarchar(20);

	Set @maxNo = 0;

	Select
		@maxNo = Isnull(Max(
			Case
				When FAM_MoveVoucherDetail.MoveVoucherCode like N'LC-%'
					and Isnumeric(Replace(FAM_MoveVoucherDetail.MoveVoucherCode, N'LC-', N'')) = 1
				Then Cast(Replace(FAM_MoveVoucherDetail.MoveVoucherCode, N'LC-', N'') as int)
				Else 0
			End
		), 0)
	From FAM_MoveVoucherDetail
	Where FAM_MoveVoucherDetail.IsDeleted = 0;

	Set @newCode = N'LC-' + Right(N'0000000' + Cast(@maxNo + 1 as nvarchar(7)), 7);

	Select @newCode as MoveVoucherCode;
End
Go

